            "getMaxLootLevel", 
            "(Lnet/minecraft/world/item/enchantment/Enchantment;)I", 
            false);
}

function search(name, replacements){
    for(var i = 0; i < replacements.length; i++){
        if(name == replacements[i].name) return replacements[i];
    }
    return null;
}

